def assign_categories(apps, schema_editor):
    DesignCategory  =   apps.get_model('design', 'DesignCategory')
    DesignStyle     =   apps.get_model('design', 'DesignStyle')
    DesignPattern   =   apps.get_model('design', 'DesignPattern')
    cats            =   {}
    for position, (slug, nombre) in enumerate(RUBROS):
        row, _        =   DesignCategory.objects.update_or_create(
            slug = slug,
            defaults = {'nombre': nombre, 'position': position, 'is_active': True},
        )
        cats[slug]     =   row
    general         =   cats['general']

    def rubro(value):
        text    =   str(value or '').strip()
        return cats.get(text) or cats.get(STYLE_RUBRO.get(text, '')) or general

    #Los patrones ya guardaban el slug del rubro; los estilos, descriptores.
    for pattern in DesignPattern.objects.all().iterator():
        pattern.categoria  =   rubro(pattern.categoria_legacy)
        pattern.save(update_fields = ['categoria'])
    for style in DesignStyle.objects.all().iterator():
        style.categoria    =   rubro(style.categoria_legacy)
        style.save(update_fields = ['categoria'])


def restore_categories(apps, schema_editor):
    DesignStyle     =   apps.get_model('design', 'DesignStyle')
    DesignPattern   =   apps.get_model('design', 'DesignPattern')
    for pattern in DesignPattern.objects.all().iterator():
        pattern.categoria_legacy = pattern.categoria.slug if pattern.categoria_id else ''
        pattern.save(update_fields = ['categoria_legacy'])
    for style in DesignStyle.objects.all().iterator():
        style.categoria_legacy = style.categoria.slug if style.categoria_id else ''
        style.save(update_fields = ['categoria_legacy'])


